3P+5/3P/5/7P/Z/7P/d/Pu+f/x/Xh3f+AMAIAA==
__PROJECT_PAYLOAD__
tar -tzf "$PAYLOAD_FILE" >/dev/null || fail "The embedded project archive is invalid."
tar -xzf "$PAYLOAD_FILE" -C "$APP_ROOT" || fail "Could not install project files."
rm -f "$PAYLOAD_FILE"
trap - EXIT
TMUX_REAL="$(command -v tmux)"
TMUX_SOCKET="${TERMINAL_MANAGER_TMUX_SOCKET:-terminal-manager-$(id -u)}"
[[ "$TMUX_SOCKET" =~ ^[A-Za-z0-9_-]{1,64}$ ]] || fail "TERMINAL_MANAGER_TMUX_SOCKET must use 1-64 letters, digits, underscores, or hyphens."
TMUX_WRAPPER="$APP_ROOT/bin/tmux-manager"
printf '#!/usr/bin/env bash\nexec %q -L %q "$@"\n' "$TMUX_REAL" "$TMUX_SOCKET" > "$TMUX_WRAPPER"
chmod 700 "$TMUX_WRAPPER"

MODE="${TERMINAL_MANAGER_MODE:-}"
if [[ -z "$MODE" ]]; then
  [[ -r /dev/tty ]] || fail "Run interactively to choose Local or Cloudflare Tunnel mode, or set TERMINAL_MANAGER_MODE=local/cloudflare."
  printf 'Launch mode: [L]ocal or [C]loudflare Tunnel? [L]: ' > /dev/tty
  IFS= read -r MODE < /dev/tty || fail "Could not read the launch mode."
fi
case "${MODE,,}" in
  ""|l|local) MODE=local ;;
  c|cloudflare|"cloudflare tunnel") MODE=cloudflare ;;
  *) fail "Choose L for Local or C for Cloudflare Tunnel." ;;
esac
install_cloudflared() {
  command_exists cloudflared && return 0
  command_exists curl || fail "curl is required to install Cloudflare Tunnel from its official package repository."
  echo "Cloudflare Tunnel was selected; installing cloudflared from Cloudflare's official signed repository."
  if command_exists apt-get; then
    run_as_root install -d -m 0755 /usr/share/keyrings
    curl -fsSL https://pkg.cloudflare.com/cloudflare-main.gpg | run_as_root tee /usr/share/keyrings/cloudflare-main.gpg >/dev/null
    printf '%s\n' 'deb [signed-by=/usr/share/keyrings/cloudflare-main.gpg] https://pkg.cloudflare.com/cloudflared any main' | run_as_root tee /etc/apt/sources.list.d/cloudflared.list >/dev/null
    run_as_root apt-get update
    run_as_root apt-get install -y cloudflared
  elif command_exists dnf || command_exists yum; then
    run_as_root mkdir -p /etc/yum.repos.d
    curl -fsSL https://pkg.cloudflare.com/cloudflared.repo | run_as_root tee /etc/yum.repos.d/cloudflared.repo >/dev/null
    if command_exists dnf; then run_as_root dnf install -y cloudflared; else run_as_root yum install -y cloudflared; fi
  else
    fail "Automatic cloudflared installation is supported on Debian-based and RPM-based systems. On this Linux distribution, install cloudflared from https://developers.cloudflare.com/cloudflare-one/networks/connectors/cloudflare-tunnel/downloads/ or choose Local mode."
  fi
  command_exists cloudflared || fail "cloudflared installation failed; install it from Cloudflare's official downloads page or choose Local mode."
}
if [[ "$MODE" == cloudflare ]]; then
  install_cloudflared
fi

PORT="${TERMINAL_MANAGER_PORT:-0}"
[[ "$PORT" =~ ^[0-9]{1,5}$ ]] || fail "TERMINAL_MANAGER_PORT must be an integer from 0 to 65535."
if (( 10#$PORT > 65535 )); then fail "TERMINAL_MANAGER_PORT must be from 0 to 65535."; fi
cd "$APP_ROOT"
echo "Starting the terminal manager on loopback. PORT=0 selects a random available port."
echo "Persistent tmux sessions use the isolated socket: $TMUX_SOCKET"
LOG_DIR="$APP_ROOT/logs"
mkdir -p "$LOG_DIR"
chmod 700 "$LOG_DIR"
SERVER_LOG="$LOG_DIR/server.log"
PORT_FILE="$APP_ROOT/state/listen-port"
rm -f "$PORT_FILE"
: > "$SERVER_LOG"
chmod 600 "$SERVER_LOG"
export HOST=127.0.0.1
export PORT
export PORT_FILE
export STATE_DIR="$APP_ROOT/state"
export TMUX_BIN="$TMUX_WRAPPER"
"$(command -v node)" "$APP_ROOT/server.js" >> "$SERVER_LOG" 2>&1 &
SERVER_PID=$!
SERVER_TAIL_PID=""
TUNNEL_PID=""
TUNNEL_TAIL_PID=""
cleanup() {
  trap - EXIT INT TERM
  [[ -n "$SERVER_TAIL_PID" ]] && kill "$SERVER_TAIL_PID" 2>/dev/null || true
  [[ -n "$TUNNEL_TAIL_PID" ]] && kill "$TUNNEL_TAIL_PID" 2>/dev/null || true
  [[ -n "$TUNNEL_PID" ]] && kill -TERM "$TUNNEL_PID" 2>/dev/null || true
  [[ -n "$SERVER_PID" ]] && kill -TERM "$SERVER_PID" 2>/dev/null || true
  [[ -n "$TUNNEL_TAIL_PID" ]] && wait "$TUNNEL_TAIL_PID" 2>/dev/null || true
  [[ -n "$SERVER_TAIL_PID" ]] && wait "$SERVER_TAIL_PID" 2>/dev/null || true
  [[ -n "$TUNNEL_PID" ]] && wait "$TUNNEL_PID" 2>/dev/null || true
  [[ -n "$SERVER_PID" ]] && wait "$SERVER_PID" 2>/dev/null || true
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

for _ in {1..300}; do
  [[ -s "$PORT_FILE" ]] && break
  if ! kill -0 "$SERVER_PID" 2>/dev/null; then
    cat "$SERVER_LOG" >&2
    fail "The terminal manager exited before it reported its listening port."
  fi
  sleep 0.1
done
[[ -s "$PORT_FILE" ]] || fail "Timed out while waiting for the terminal manager to start."
BOUND_PORT="$(tr -d '\r\n' < "$PORT_FILE")"
[[ "$BOUND_PORT" =~ ^[0-9]{1,5}$ ]] && (( BOUND_PORT >= 1 && BOUND_PORT <= 65535 )) || fail "The server returned an invalid listening port."

if [[ "$MODE" == local ]]; then
  echo "Local URL: http://127.0.0.1:$BOUND_PORT"
  echo "On first visit, set the password and enroll the authenticator in the web panel."
else
  TUNNEL_LOG="$LOG_DIR/cloudflared.log"
  : > "$TUNNEL_LOG"
  chmod 600 "$TUNNEL_LOG"
  cloudflared tunnel --no-autoupdate --url "http://127.0.0.1:$BOUND_PORT" >> "$TUNNEL_LOG" 2>&1 &
  TUNNEL_PID=$!
  PUBLIC_URL=""
  for _ in {1..600}; do
    PUBLIC_URL="$(grep -Eo 'https://[[:alnum:]-]+\.trycloudflare\.com' "$TUNNEL_LOG" | head -n 1 || true)"
    [[ -n "$PUBLIC_URL" ]] && break
    if ! kill -0 "$TUNNEL_PID" 2>/dev/null; then
      cat "$TUNNEL_LOG" >&2
      fail "Cloudflare Tunnel exited before providing a URL."
    fi
    sleep 0.1
  done
  [[ -n "$PUBLIC_URL" ]] || { cat "$TUNNEL_LOG" >&2; fail "Timed out waiting for the Cloudflare Tunnel URL."; }
  echo "Cloudflare Tunnel URL: $PUBLIC_URL"
  echo "Keep this first-run URL private until the password and authenticator are set in the panel."
fi
tail -n +1 -f "$SERVER_LOG" &
SERVER_TAIL_PID=$!
if [[ "$MODE" == cloudflare ]]; then
  tail -n +1 -f "$TUNNEL_LOG" &
  TUNNEL_TAIL_PID=$!
  set +e
  wait -n "$SERVER_PID" "$TUNNEL_PID"
  STATUS=$?
  set -e
else
  set +e
  wait "$SERVER_PID"
  STATUS=$?
  set -e
fi
exit "$STATUS"
